import set, { unsafeSet } from "../index.js";
import { expect } from "chai";
describe("Test set", function () {
  it("check set result", function () {
    var obj = {};
    set(obj, ["a", "b"], "c");
    expect(obj).to.deep.equal({
      a: {
        b: "c"
      }
    });
  });
});
describe("CVE-2020-28281", function () {
  it("should not overwrite prototype", function () {
    var obj = {};
    expect(obj.isAdmin).to.be.undefined;
    expect(function () {
      return set(obj, ['__proto__', 'isAdmin'], true);
    }).to["throw"]();
    expect(function () {
      return set(obj, ['constructor', 'isAdmin'], true);
    }).to["throw"]();
    expect(function () {
      return set(obj, ['prototype', 'isAdmin'], true);
    }).to["throw"]();
    expect(obj.isAdmin).to.be.undefined;
    set(obj, ["isAdmin"], true);
    expect(obj.isAdmin).to.be["true"];
  });
  it("should force overwrite prototype with unsafe mode", function () {
    var obj = {};
    unsafeSet(obj, ['__proto__', 'fake'], true);
    expect(obj.fake).to.be["true"];
  });
});
describe("Test append", function () {
  it("test simple append", function () {
    var obj = {};
    set(obj, ["a"], "a1", true);
    set(obj, ["a"], "a2", true);
    expect(obj).to.deep.equal({
      a: ["a1", "a2"]
    });
  });
  it("should keep origin value", function () {
    var obj = {};
    set(obj, ["a"], "a3");
    set(obj, ["a"], "a4", true);
    expect(obj).to.deep.equal({
      a: ["a3", "a4"]
    });
  });
});